<div class="modal fade payment-status-modal" id="paymentStatusModal" tabindex="-1" role="dialog" aria-labelledby="paymentStatusModalTitle" aria-hidden="true"><div class="modal-dialog modal-dialog-centered modal-dialog-scrollable" role="document"><div class="modal-content"><form id="paymentStatusForm" method="post" action="<?= base_url('admin/payment-statuses/save') ?>"><?= csrf_field() ?><div class="modal-header"><div><div class="payment-status-eyebrow">PAYMENT STATUS MASTER</div><h2 class="modal-title h5 mb-0" id="paymentStatusModalTitle">Add payment status</h2></div><button type="button" class="close" data-dismiss="modal" aria-label="Close">&times;</button></div><div class="modal-body"><input type="hidden" name="id" id="paymentStatusId"><div class="payment-status-form-grid"><div class="form-group"><label for="paymentStatusName">Status name</label><input class="form-control" name="status_name" id="paymentStatusName" required maxlength="120"><div class="validation-error" id="status_nameErr"></div></div><div class="form-group"><label for="paymentStatusCode">Status code</label><input class="form-control" name="status_code" id="paymentStatusCode" required maxlength="60" pattern="[a-z0-9][a-z0-9_-]{1,59}" placeholder="e.g. pending"><small class="form-text">Lowercase code used by payment records and transitions.</small><div class="validation-error" id="status_codeErr"></div></div><div class="form-group payment-status-form-wide"><label for="paymentStatusDescription">Description</label><textarea class="form-control" name="description" id="paymentStatusDescription" maxlength="500" rows="3"></textarea><div class="validation-error" id="descriptionErr"></div></div><div class="form-group"><label for="paymentStatusSort">Sort order</label><input class="form-control" type="number" min="0" name="sort_order" id="paymentStatusSort" value="0" required><div class="validation-error" id="sort_orderErr"></div></div><div class="form-group"><label for="paymentStatusState">Active/inactive status</label><select class="form-control" name="status" id="paymentStatusState"><option value="1">Active</option><option value="0">Inactive</option></select><div class="validation-error" id="statusErr"></div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-dismiss="modal">Cancel</button><button class="btn theme-btn" type="submit">Save status</button></div></form></div></div></div>
<script>
(function () {
    'use strict';
    if (window.rootinsPaymentStatusInlineBound) return;
    window.rootinsPaymentStatusInlineBound = true;
    var modal = document.getElementById('paymentStatusModal');
    var form = document.getElementById('paymentStatusForm');
    if (!modal || !form) return;
    var title = document.getElementById('paymentStatusModalTitle');
    var submit = form.querySelector('button[type="submit"]');
    function clearErrors() { form.querySelectorAll('.validation-error').forEach(function (node) { node.textContent = ''; }); form.querySelectorAll('.is-invalid').forEach(function (node) { node.classList.remove('is-invalid'); }); }
    function closeModal() { modal.classList.remove('show'); modal.style.display = 'none'; modal.setAttribute('aria-hidden', 'true'); document.querySelectorAll('.payment-status-modal-backdrop').forEach(function (node) { node.remove(); }); document.body.classList.remove('modal-open', 'payment-status-modal-open'); if (window.hide_loader) window.hide_loader(); }
    function openModal() { document.querySelectorAll('.payment-status-modal-backdrop').forEach(function (node) { node.remove(); }); var backdrop = document.createElement('div'); backdrop.className = 'modal-backdrop fade show payment-status-modal-backdrop'; document.body.appendChild(backdrop); document.body.appendChild(modal); modal.style.display = 'block'; modal.classList.add('show'); modal.setAttribute('aria-hidden', 'false'); document.body.classList.add('modal-open', 'payment-status-modal-open'); }
    function resetForm() { form.reset(); document.getElementById('paymentStatusId').value = ''; document.getElementById('paymentStatusSort').value = '0'; title.textContent = 'Add payment status'; clearErrors(); }
    function showErrors(errors) { Object.keys(errors || {}).forEach(function (key) { var field = form.querySelector('[name="' + key + '"]'); var error = document.getElementById(key + 'Err'); if (field) field.classList.add('is-invalid'); if (error) error.textContent = errors[key]; }); }
    function populate(row) { resetForm(); document.getElementById('paymentStatusId').value = row.id || ''; document.getElementById('paymentStatusName').value = row.status_name || ''; document.getElementById('paymentStatusCode').value = row.status_code || ''; document.getElementById('paymentStatusDescription').value = row.description || ''; document.getElementById('paymentStatusSort').value = row.sort_order || 0; document.getElementById('paymentStatusState').value = String(row.status || 0); title.textContent = 'Edit payment status'; openModal(); }
    document.addEventListener('click', function (event) { var reset = event.target.closest('[data-payment-status-reset="1"]'); var edit = event.target.closest('.js-payment-status-edit'); var close = event.target.closest('#paymentStatusModal [data-dismiss="modal"]'); if (reset) { event.preventDefault(); resetForm(); openModal(); } else if (edit) { event.preventDefault(); try { populate(JSON.parse(edit.getAttribute('data-payment-status') || '{}')); } catch (error) { if (window.showError) window.showError('The payment status could not be loaded.'); } } else if (close) { event.preventDefault(); closeModal(); } });
    form.addEventListener('submit', async function (event) { event.preventDefault(); if (submit.disabled) return; clearErrors(); submit.disabled = true; submit.setAttribute('aria-busy', 'true'); if (window.show_loader) window.show_loader(); try { var response = await fetch(form.action, { method: 'POST', body: new FormData(form), headers: { 'X-Requested-With': 'XMLHttpRequest', 'X-CSRF-TOKEN': (form.querySelector('[name="csrf_rtn"]') || {}).value || '' } }); var payload = await response.json(); if (!response.ok || !payload.status) { showErrors(payload.errors || {}); if (window.showError) window.showError(payload.msg || 'Payment status could not be saved.'); return; } if (window.showSuccess) window.showSuccess(payload.msg || 'Payment status saved.'); resetForm(); closeModal(); window.setTimeout(function () { window.location.reload(); }, 500); } catch (error) { if (window.showError) window.showError('The payment status request failed. Please try again.'); } finally { submit.disabled = false; submit.removeAttribute('aria-busy'); if (window.hide_loader) window.hide_loader(); } });
}());
</script>
<script defer src="<?= base_url('assets/js/admin/payment_status.js?v=20261012.6') ?>"></script>
